ImVec4 withAlpha(ImVec4 c, float a) { return ImVec4(c.x, c.y, c.z, a); }

// Mode combo: index 0 = AUTO, then kFirstMode upward.
std::string modeArg(int idx) {
  return idx == 0 ? "AUTO" : "M" + std::to_string(idx + kFirstMode - 1);
}

std::string clockNow() {
  const std::time_t t = std::time(nullptr);
  std::tm tm{};
  localtime_r(&t, &tm);
  char b[16];
  std::strftime(b, sizeof(b), "%H:%M:%S", &tm);
  return b;
}

// Perceptual waterfall ramp: near-black navy -> violet -> orange -> pale
// yellow, as a 256-entry lookup in ImGui's packed (ABGR) format.
const std::vector<uint32_t>& waterfallLut() {
  static const std::vector<uint32_t> lut = [] {
    struct Stop { float t, r, g, b; };
    const Stop s[] = {{0.00f, 0.04f, 0.05f, 0.10f}, {0.25f, 0.11f, 0.16f, 0.42f},
                      {0.50f, 0.48f, 0.18f, 0.56f}, {0.70f, 0.88f, 0.33f, 0.24f},
                      {0.86f, 0.97f, 0.64f, 0.23f}, {1.00f, 0.99f, 0.97f, 0.71f}};
    std::vector<uint32_t> v(256);
    for (int i = 0; i < 256; ++i) {
      const float t = float(i) / 255.0f;
      int k = 0;
      while (k < 4 && t > s[k + 1].t) ++k;
      const float u = (t - s[k].t) / (s[k + 1].t - s[k].t);
      auto lerp = [&](float a, float b) { return a + (b - a) * u; };
      v[size_t(i)] = IM_COL32(int(lerp(s[k].r, s[k + 1].r) * 255.0f),
                              int(lerp(s[k].g, s[k + 1].g) * 255.0f),
                              int(lerp(s[k].b, s[k + 1].b) * 255.0f), 255);
    }
    return v;
  }();
  return lut;
}

// Rounded status chip.
// Status pill; with `clickable`, returns true when clicked (same shape, so
// a row of pills lines up whatever mixes of the two it holds).
bool pill(const char* text, ImVec4 c, bool clickable = false) {
  ImDrawList* dl = ImGui::GetWindowDrawList();
  const ImVec2 pad(10.0f, 3.0f);
  const ImVec2 ts = ImGui::CalcTextSize(text);
  const ImVec2 p = ImGui::GetCursorScreenPos();
  const ImVec2 q(p.x + ts.x + 2 * pad.x, p.y + ts.y + 2 * pad.y);
  const ImVec2 size(q.x - p.x, q.y - p.y);
  bool clicked = false;
  bool hovered = false;
  if (clickable) {
    clicked = ImGui::InvisibleButton(text, size);
    hovered = ImGui::IsItemHovered();
    if (hovered) ImGui::SetMouseCursor(ImGuiMouseCursor_Hand);
  } else {
    ImGui::Dummy(size);
  }
  dl->AddRectFilled(p, q, ImGui::GetColorU32(withAlpha(c, hovered ? 0.32f : 0.18f)), 999.0f);
  dl->AddRect(p, q, ImGui::GetColorU32(withAlpha(c, 0.55f)), 999.0f);
  dl->AddText(ImVec2(p.x + pad.x, p.y + pad.y), ImGui::GetColorU32(c), text);
  return clicked;
}

// Label over a large value (top-bar statistic).
void stat(const char* label, const std::string& value, ImFont* big) {
  ImGui::BeginGroup();
  ImGui::PushStyleColor(ImGuiCol_Text, col::dim);
  ImGui::TextUnformatted(label);
  ImGui::PopStyleColor();
  if (big) ImGui::PushFont(big);
  ImGui::TextUnformatted(value.c_str());
  if (big) ImGui::PopFont();
  ImGui::EndGroup();
}

// Card: a bordered child with a small dim caption. Controls that belong
// on the caption row go through cardHeaderRight() before the body.
float g_cardTitleY = 0.0f;
bool beginCard(const char* id, const char* title, ImVec2 size) {
  ImGui::PushStyleColor(ImGuiCol_ChildBg, col::card);
  const bool open = ImGui::BeginChild(id, size, ImGuiChildFlags_Borders,
                                      ImGuiWindowFlags_NoScrollbar);
  g_cardTitleY = ImGui::GetCursorPosY();
  ImGui::AlignTextToFramePadding();
  ImGui::PushStyleColor(ImGuiCol_Text, col::dim);
  ImGui::TextUnformatted(title);
  ImGui::PopStyleColor();
  return open;
}
// Right-align `width` pixels of controls on the caption row.
void cardHeaderRight(float width) {
  ImGui::SameLine(ImGui::GetWindowContentRegionMax().x - width);
  ImGui::SetCursorPosY(g_cardTitleY);
}
void endCard() {
  ImGui::EndChild();
  ImGui::PopStyleColor();
}

// Horizontal level bar, -100..0 dBFS, with the value at the right.
void levelBar(const char* label, float db, ImVec4 c) {
  const float frac = std::clamp((db + 100.0f) / 100.0f, 0.0f, 1.0f);
  ImGui::PushStyleColor(ImGuiCol_Text, col::dim);
  ImGui::TextUnformatted(label);
  ImGui::PopStyleColor();
  ImGui::SameLine(70.0f);
  const float w = ImGui::GetContentRegionAvail().x - 82.0f;
  const ImVec2 p = ImGui::GetCursorScreenPos();
  const float h = ImGui::GetTextLineHeight() * 0.55f;
  const float y = p.y + (ImGui::GetTextLineHeight() - h) * 0.5f;
  ImDrawList* dl = ImGui::GetWindowDrawList();
  dl->AddRectFilled(ImVec2(p.x, y), ImVec2(p.x + w, y + h),
                    ImGui::GetColorU32(col::raised), h * 0.5f);
  if (frac > 0.0f) {
    dl->AddRectFilled(ImVec2(p.x, y), ImVec2(p.x + w * frac, y + h),
                      ImGui::GetColorU32(c), h * 0.5f);
  }
  ImGui::Dummy(ImVec2(w, ImGui::GetTextLineHeight()));
  ImGui::SameLine();
  ImGui::Text("%6.1f", double(db));
}

std::map<std::string, std::string> parseFields(const std::string& line) {
  std::map<std::string, std::string> out;
  size_t i = 0;
  while (i < line.size()) {
    const size_t j = line.find(' ', i);
    const std::string tok = line.substr(i, j == std::string::npos ? std::string::npos : j - i);
    const size_t eq = tok.find('=');
    if (eq != std::string::npos) out[tok.substr(0, eq)] = tok.substr(eq + 1);
    if (j == std::string::npos) break;
    i = j + 1;
  }
  return out;
}

std::string field(const std::map<std::string, std::string>& f, const char* k,
                  const char* dflt = "-") {
  auto it = f.find(k);
  return it == f.end() || it->second.empty() ? dflt : it->second;
}

