void GuiInstruments::push(const Telemetry& t) {
  auto trim = [](auto& q) {
    while (q.size() > kHistory) q.pop_front();
  };
  rxLevel.push_back(t.rxLevelDbfs);
  noiseFloor.push_back(t.noiseFloorDbfs);
  modeHistory.push_back(t.mode);
  trim(rxLevel);
  trim(noiseFloor);
  trim(modeHistory);
}

// The command log is on screen (and in screenshots): a secret argument
// is never put in it. ENCRYPTKEY's argument is the PSK itself.
std::string Gui::redactForLog(const std::string& cmd) {
  const size_t a = cmd.find_first_not_of(" \t");
  if (a == std::string::npos) return cmd;
  const size_t b = cmd.find_first_of(" \t", a);
  const std::string verb = toUpper(cmd.substr(a, b == std::string::npos ? b : b - a));
  if (verb != "ENCRYPTKEY" || b == std::string::npos) return cmd;
  return cmd.substr(0, b) + " ********";
}

Gui::Gui(ModemWorker& worker)
    : worker_(worker),
      exec_(std::make_unique<ControlExecutor>(
          [&worker](const std::string& l) { return worker.control(l); })) {}
Gui::~Gui() { shutdown(); }

void Gui::pushLog(const std::string& cmd, const std::string& resp) {
  log_.push_back({redactForLog(cmd), resp, clockNow()});
  while (log_.size() > 200) log_.pop_front();
}

std::string Gui::submit(const std::string& cmd) {
  // THE rule: no privileged path. Everything the GUI changes goes through
  // the same dispatcher the TCP control port uses.
  const std::string resp = worker_.control(cmd);
  pushLog(cmd, resp);
  return resp;
}

void Gui::send(const std::string& cmd, std::function<void(const std::string&)> then) {
  const uint64_t tag = nextTag_++;
  if (then) pending_[tag] = std::move(then);
  exec_->post(cmd, tag);
}

void Gui::drainResults() {
  for (auto& r : exec_->takeResults()) {
    pushLog(r.line, r.response);
    auto it = pending_.find(r.tag);
    if (it != pending_.end()) {
      it->second(r.response);
      pending_.erase(it);
    }
  }
}

void Gui::sampleTelemetry() {
  snap_ = worker_.telemetry();
  inst_.push(snap_);
  // Published by the worker, never under its mutex (see gui.hpp).
  const double nowSec = double(SDL_GetTicks64()) / 1000.0;
  if (nowSec - lastStatusSec_ >= 0.25) {
    lastStatusSec_ = nowSec;
    refreshStatus();
  }
}

